/**
 * Minecraft Java Edition LCG Random (java.util.Random clone)
 * Required for exact seed derivation.
 */
class Java_Random{
    constructor(seed){
        this.set_seed(seed);
    }
    set_seed(seed){
        const masked = (BigInt(seed) ^ 0x5DEECE66Dn) & 0xFFFFFFFFFFFFn;
        this.seed = (masked * 0x5DEECE66Dn + 0xBn) & 0xFFFFFFFFFFFFn;
    }
    
    next(bits){
        this.seed = (this.seed * 0x5DEECE66Dn + 0xBn) & 0xFFFFFFFFFFFFn;
        return Number(this.seed >> (48n - BigInt(bits)));
    }
    next_int(bound){
        let r = this.next(31);
        let m = bound - 1;
        // the condition is only true if bound is a power of 2;
        if((bound & m) === 0){
            r = Number((BigInt(bound) * BigInt(r)) >> 31n);
        }
        else{
            let u = r;
            while(u - (r = u % bound) + m < 0){
                u = this.next(31);
            }
        }
        return r;
    }
    next_double(){
        const high = BigInt(this.next(26));
        const low = BigInt(this.next(27));
        return Number((high << 27n) + low) / 9007199254740992.0;
    }
}

/**
 * Simplified Perlin Octave Noise Sampler resembling Minecraft's layout.
 * Minecraft shifts sample coordinates based on seed-hashed octave offsets.
 */
class Noise_Layer{
    constructor(seed, octaves){
        this.octaves = octaves;
        // unused since Gemini is apparently scared of perlin noise;
        const PRNG = new Java_Random(seed);
        
        // this should give pseudo-random per-octave permutations/offsets matching Minecraft;
        // according to Gemini;
        this.amplitudes = Array(octaves).fill(0).map((_,i) => 0.5**i);
    }
    
    // Gemini decided to use a coherent noise function placeholder;
    // instead of just normal perlin noise;
    // which is really stupid; i want the noise that Minecraft actually uses; not a formula that's not seed dependent;
    // though this could maybe still be informative;
    // but also the inability to change with the seed makes this less informative;
    raw_noise(x, y){
        return (Math.sin(x * 12.9898 + y * 78.233) * 43758.5453) % 1;
    }
    noise(x, y){
        let total = 0;
        let freq = 1;
        let max = 0;
        
        for(let i = 0; i < this.octaves.length; i++){
            let amp = this.amplitudes[i];
            total += this.raw_noise(x * freq, y * freq) * amp;
            max += amp;
            freq *= 2;
        }
        return total / max; // Normalized between roughly -1 and 1
    }
}

/**
 * T, H, C, E, W Biome Noise Generator
 */
class Biome_Noise{
    constructor(){
        // I'm using this as a singleton since I only need one active at a time :shrug:;
    }
    set_seed(world_seed){
        // Minecraft derives separate internal seeds for each noise type using large prime constants;
        // but our PRNG only uses 1 prime number, so maybe Gemini is wrong about this too;
        const base_seed = BigInt(world_seed);
        // Offsets/Seeds mapped from net.minecraft.world.gen.noise.NoiseParametersKeys???
        // well, maybe that's where they are from;
        this.C_N = new Noise_Layer(Number(base_seed ^ 0x3n), [1, 1, 2, 4]);
        this.E_N = new Noise_Layer(Number(base_seed ^ 0x5n), [1, 1, 2]);
        this.T_N = new Noise_Layer(Number(base_seed ^ 0x1n), [1, 2, 1]);
        this.H_N = new Noise_Layer(Number(base_seed ^ 0x2n), [1, 1, 1]);
        this.W_N = new Noise_Layer(Number(base_seed ^ 0x4n), [1, 2, 4, 8]);
        // these are so you can pan the noise maps separately in the tool;
        this.C_O = {x: 0, z:0};
        this.E_O = {x: 0, z:0};
        this.T_O = {x: 0, z:0};
        this.H_O = {x: 0, z:0};
        this.W_O = {x: 0, z:0};
    }
    /**
     * Scaled down typically by a factor of 0.25 (Quarter-resolution sampling used by MC)
     * - typically? the wiki implies it is ALWAYS scaled down by that factor;
     * @param {Noise_Layer} noise_layer ;
     */
    noise(x, z, noise_layer){
        const scale = 0.25;
        return noise_layer.noise(x * scale, z * scale);
    }
    noises(x, z){
        return {
            C: this.noises(x + this.C_O.x, z + this.C_O.z, this.C_N),
            E: this.noises(x + this.E_O.x, z + this.E_O.z, this.E_N),
            T: this.noises(x + this.T_O.x, z + this.T_O.z, this.T_N),
            H: this.noises(x + this.H_O.x, z + this.H_O.z, this.H_N),
            W: this.noises(x + this.W_O.x, z + this.W_O.z, this.W_N),
        }
    }
}
const biome_noise = new Biome_Noise();
window.biome_noise = biome_noise;
